with metrics as (select id, session_id, event_type, page, event_time, duration_sec, percent_rank() over (partition by event_type order by duration_sec desc nulls last) as duration_sec_percent_rank, count(duration_sec) over (partition by page) as page_count_duration_sec from web_events) select case when duration_sec >= 484 then 'PREMIUM' else 'STANDARD' end as duration_sec_tier, sort_array(collect_set(page)) as page_list, stddev_samp(duration_sec) as duration_sec_stddev, sort_array(collect_set(event_type)) as event_type_list, bit_and(duration_sec) as duration_sec_bit_and, max(event_time) as ended_at from metrics group by case when duration_sec >= 484 then 'PREMIUM' else 'STANDARD' end order by duration_sec_stddev desc
